    /** Fixed number of subdivision steps per segment (default: 30) */
    subdivisions?: number;
    /** Maximum Euclidean length of any sub-segment in scene units */
    maxSegmentLength?: number;
    /** Flatness or spatial error tolerance threshold */
    tolerance?: number;
    /** Normalized accuracy multiplier [0.1 .. 10.0] (default: 1.0) */
    accuracy?: number;
}

