import { SubdivisionEngine, Vec2 } from "retiam";

const p0 = new Vec2(-16, -5);
const p1 = new Vec2(-7, 11);
const p2 = new Vec2(6, -10);
const p3 = new Vec2(16, 7);

// Split at parameter t = 0.65
const [leftCurve, rightCurve] = SubdivisionEngine.splitCubicBezier(p0, p1, p2, p3, 0.65);

// leftCurve:  [P0, Q0, R0, S]
// rightCurve: [S, R1, Q2, P3]

public static subdivideCubicBezier(
    p0: Vec2, p1: Vec2, p2: Vec2, p3: Vec2, depth: number = 3
): [Vec2, Vec2, Vec2, Vec2][] {
    if (depth <= 0) return [[p0, p1, p2, p3]];

    const [left, right] = this.splitCubicBezier(p0, p1, p2, p3, 0.5);
    return [
        ...this.subdivideCubicBezier(left[0], left[1], left[2], left[3], depth - 1),
        ...this.subdivideCubicBezier(right[0], right[1], right[2], right[3], depth - 1),
    ];
}

